<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Services\CmsQuery as Q; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status'), 'type' => V::queryString('type'), 'category' => (int) V::queryString('category')];
$result = CmsContent::posts($filters, V::queryPage());
$cats = ['0' => 'Todas as categorias']; foreach (CmsContent::categories() as $c) { $cats[$c['id']] = $c['title']; }
$tabs = [['/conteudos', 'Todos', (int) Q::value('SELECT COUNT(*) FROM posts WHERE deleted_at IS NULL'), $filters['type'] === '']];
foreach (CmsContent::POST_TYPES as $key => $label) { $tabs[] = ['/conteudos?type=' . $key, $label, (int) Q::value('SELECT COUNT(*) FROM posts WHERE deleted_at IS NULL AND post_type=?', [$key]), $filters['type'] === $key]; }
$this->start('actions'); ?><a class="cms-btn" href="/conteudos/categorias">Categorias</a><a class="cms-btn" href="/conteudos/faq">FAQ</a><a class="cms-btn-primary" href="/conteudos/novo<?= $filters['type'] !== '' ? '?type=' . V::e($filters['type']) : '' ?>"><?= V::icon('plus') ?>Novo conteúdo</a><?php $this->stop(); ?>
<?= V::tabs($tabs, 'Tipo de conteúdo') ?>
<section class="cms-list"><?= V::listHead('Lista de conteúdos', $result['total'] . ' registro(s)', V::searchForm('Buscar por título', ['type' => [$filters['type'], ['' => 'Todos os tipos'] + CmsContent::POST_TYPES, 'Tipo'], 'category' => [$filters['category'], $cats, 'Categoria'], 'status' => [$filters['status'], ['' => 'Todas', 'draft' => 'Rascunho', 'published' => 'Publicado'], 'Situação']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum conteúdo encontrado.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Conteúdos"><table><thead><tr><th>Conteúdo</th><th>Tipo</th><th>Categoria</th><th>Status</th><th>Publicação</th><th class="cms-th-actions">Ações</th></tr></thead><tbody>
<?php foreach ($result['rows'] as $row): ?><tr><td><div class="cms-cell"><?= $row['cover'] ? '<img class="cms-thumb" src="' . V::e($row['cover']) . '" alt="">' : '<i class="cms-thumb">' . V::icon('edit') . '</i>' ?><a href="/conteudos/<?= (int) $row['id'] ?>"><?= V::e($row['title']) ?></a></div></td><td><?= V::e(CmsContent::POST_TYPES[$row['post_type']] ?? $row['post_type']) ?></td><td><?= V::e($row['category_title'] ?? '—') ?></td><td><?= V::badge($row['status'], $row['status'] === 'published' ? 'Publicado' : 'Rascunho') ?></td><td><?= V::date($row['post_at']) ?></td><td class="cms-td-actions"><?= V::iconLink('/conteudos/' . (int) $row['id'], 'Editar') ?><?= V::iconAction('post-delete', 'Excluir', ['id' => $row['id']], 'Excluir este conteúdo?') ?></td></tr><?php endforeach; ?>
</tbody></table></div><?= V::pager($result) ?><?php endif; ?></section>
